from pathlib import Path
replacements = {
    'pyknotid/spacecurves/spacecurve.py': {
        'np.float': 'float',
        'np.bool': 'bool',
    },
    'pyknotid/spacecurves/periodiccell.py': {
        'np.int': 'np.int64',
    },
    'pyknotid/spacecurves/ccomplexity.pyx': {
        'np.int': 'np.int64',
    },
}
for name, pairs in replacements.items():
    p = Path(name)
    s = p.read_text()
    old = s
    for a, b in pairs.items():
        s = s.replace(a, b)
    if s != old:
        p.write_text(s)
        print('patched', name)
